INSERT INTO public.ulbs (id, slug, name, code, type, district, state, logo_url, hero_image_url, about, vision, mission, address, phone, email, website, established_year, population, area_sqkm, primary_color, is_active, created_at, updated_at) VALUES ('232c9fe7-c48c-479c-9676-07f2cdfbf9e4', 'mulugu', 'Mulugu', '302731', 'Municipality', 'Mulugu ', 'Telangana', NULL, NULL, 'Mulugu Municipality is an Urban Local Body in Mulugu district, Telangana, committed to providing efficient civic services and promoting sustainable urban development. The municipality strives to ensure cleanliness, public health, quality infrastructure, safe drinking water, sanitation and environmental conservation. Through transparent governance and active public participation, Mulugu Municipality is dedicated to creating a clean, green, and citizen-friendly town while improving the quality of life for all residents.Clean and hygienic municipal administration.
