INSERT INTO public.ulbs (id, slug, name, code, type, district, state, logo_url, hero_image_url, about, vision, mission, address, phone, email, website, established_year, population, area_sqkm, primary_color, is_active, created_at, updated_at) VALUES ('82f7c59a-e4a0-46e7-b2bf-2f98a32bb69a', 'devarakadara', 'Devarakadara', '1310', 'Municipality', 'Mahabubnagar', 'Telangana', NULL, 'https://hvhpehdwmgrljvfekzbf.supabase.co/storage/v1/object/sign/public-assets/ulbs/devarakadara/hero_image_url-1785223256755-devarakadra_logo.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV82YTFjMDZmNi05MmIxLTQ5ODQtYTQ2MS1kOTcyNjE3ZjU4Y2IiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwdWJsaWMtYXNzZXRzL3VsYnMvZGV2YXJha2FkYXJhL2hlcm9faW1hZ2VfdXJsLTE3ODUyMjMyNTY3NTUtZGV2YXJha2FkcmFfbG9nby5qcGciLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg1MjIzMjU3LCJleHAiOjIxMDA1ODMyNTd9.wyo1ZVciN_vw7PrZfq60EjAmtESZyWoVm7hgO9BgdAg', 'Devarkadra muncipality is an urban local body in the Mahabubnagar district of Telangana,India.It administers the civic services and urban development of Devarakadra town.
INSERT INTO public.ulbs (id, slug, name, code, type, district, state, logo_url, hero_image_url, about, vision, mission, address, phone, email, website, established_year, population, area_sqkm, primary_color, is_active, created_at, updated_at) VALUES ('9fe4af6d-5bce-4724-b08f-58257668c239', 'kohir', 'Kohir', '302302', 'Municipality', 'Sangareddy ', 'Telangana', NULL, NULL, 'Kohir is a town and the administrative headquarters of Kohir mandal in Sangareddy district, Telangana, India, located on the Deccan Plateau approximately 100 kilometers northwest of Hyderabad.[1] With a town population of around 15,075 as of the 2011 census and a mandal-wide population of 60,638, it serves as a rural hub characterized by semi-arid terrain and red soil that gives the area its name, derived from the local term for "red diamond."[2][1]Historically, Kohir has been a cultural and religious center since at least the 12th century during the Kalyana Chalukya era, with evidence of Shaivite practices and warfare memorials, including a recently discovered rare three-tiered Veeragallu (hero stone) sculpture depicting a warrior''s valor and ascension to heaven.[3] The town''s economy revolves around agriculture, leveraging its fertile red soil for crops such as grains, ginger, and fruits; it is particularly notable for guava cultivation, with the local Kohir variety serving as a key parent in developing high-yielding hybrids like Safed Jam and Kohir Safeda, adapted to semi-arid tropical conditions in Telangana.[4] These hybrids emphasize larger fruits, fewer seeds, and robust growth, supporting both fresh consumption and processing industries in the region.[4] Kohir''s landscape also features ancient temple ruins and sculptures, underscoring its enduring significance as a site of historical and archaeological interest.  Kohir lies on the Deccan Plateau and has historically functioned as an agrarian settlement. Archaeological remains such as hero stones (veeragallu) found in the Sangareddy region indicate early habitation by warrior and farming communities.[3]
INSERT INTO public.ulbs (id, slug, name, code, type, district, state, logo_url, hero_image_url, about, vision, mission, address, phone, email, website, established_year, population, area_sqkm, primary_color, is_active, created_at, updated_at) VALUES ('862b38db-af42-4290-9638-3ddef736d469', 'aswaraopeta', 'Aswaraopeta', '1308', 'Municipality', 'Bhadradri Kothagudem ', 'Telangana', NULL, '/uploads/aswaraopet-hero.jpg', 'Aswaraopeta Municipality is an Urban Local Body Notified on 27-01-2025 in Bhadradri Kothagudem District of Telangana. It is responsible for providing civic amenities, public health, sanitation, drinking water supply, street lighting, roads, drainage, parks, town planning, and citizen services while promoting sustainable urban development
INSERT INTO public.ulbs (id, slug, name, code, type, district, state, logo_url, hero_image_url, about, vision, mission, address, phone, email, website, established_year, population, area_sqkm, primary_color, is_active, created_at, updated_at) VALUES ('e112a98b-e438-45eb-9f92-eee4768ab87d', 'gummadidala', 'Gummadidala', '1313', 'Municipality', 'Sangareddy', 'Telangana', NULL, 'https://hvhpehdwmgrljvfekzbf.supabase.co/storage/v1/object/sign/public-assets/ulbs/gummadidala/hero_image_url-1785148962210-gumadidhala_office.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV82YTFjMDZmNi05MmIxLTQ5ODQtYTQ2MS1kOTcyNjE3ZjU4Y2IiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwdWJsaWMtYXNzZXRzL3VsYnMvZ3VtbWFkaWRhbGEvaGVyb19pbWFnZV91cmwtMTc4NTE0ODk2MjIxMC1ndW1hZGlkaGFsYV9vZmZpY2UucG5nIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NTE0ODk2MywiZXhwIjoyMTAwNTA4OTYzfQ.qyS3Vbl1YqRdho3_diN-I-UGE6sNicP9G5nzLxxtzps', 'Gummadidala is a historic village and mandal headquarters originally part of Medak district that is now administered under the Sangareddy district of Telangana, India, renowned for its ancient regional shrines and agrarian roots.
INSERT INTO public.ulbs (id, slug, name, code, type, district, state, logo_url, hero_image_url, about, vision, mission, address, phone, email, website, established_year, population, area_sqkm, primary_color, is_active, created_at, updated_at) VALUES ('d7416ee0-4876-42a9-9bd8-699a2ecc7a1c', 'moinabad', 'Moinabad', '302299', 'Municipality', 'Rangareddy', 'Telangana', NULL, 'https://hvhpehdwmgrljvfekzbf.supabase.co/storage/v1/object/sign/public-assets/ulbs/moinabad/hero_image_url-1785240154959-Moinabad_office.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV82YTFjMDZmNi05MmIxLTQ5ODQtYTQ2MS1kOTcyNjE3ZjU4Y2IiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwdWJsaWMtYXNzZXRzL3VsYnMvbW9pbmFiYWQvaGVyb19pbWFnZV91cmwtMTc4NTI0MDE1NDk1OS1Nb2luYWJhZF9vZmZpY2UuanBnIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NTI0MDE1NiwiZXhwIjoyMTAwNjAwMTU2fQ.qGgmIQUVDOwjep-qgfoI7EnTGOuIq4gr1kDu87bwg1s', 'The Moinabad Municipality by merging of 9 Gram Panchayaths on 27.01.2025 i.e Appojiguda, Aziznagar, Chilkur, Himayathnagar, Moinabad, Murthuzaguda, Peddamangalaram, Surangal, Yenkepally. ', 'To develop Moinabad Municipality as a clean, green, healthy, sustainable and well-planned urban local body by providing efficient civic services, modern infrastructure, transparent governance and a better quality of life for all citizens', 'Ensure cleanliness, sanitation and effective solid waste management.
